    private static long bytesTo8ByteLong(byte[] buf) {
        assert buf.length == 8 : "expected 8 bytes for long";
        long result = 0;
        for (int i = 0; i < 8; i++) {
            result |= ((long) (buf[i] & 0xFF)) << (56 - i * 8);
