        return result;
    }

    // -- OPE domain derivation -----------------------------------------------

    /** Maximum domain for OPE before recursion becomes impractical. */
    private static final long OPE_DOMAIN_CAP = 1L << 48;

    /** Default range/domain ratio. */
    private static final long OPE_RANGE_RATIO = 10L;

    /**
     * Derives the OPE domain and range from the field type.
     *
     * <p>The returned array contains {@code [domain, range]} where domain is the plaintext
     * space size and range is the ciphertext space size ({@code domain * 10}).
     *
     * @param type the field type; must be OPE-compatible (numeric primitive or BoundedString)
     * @return a two-element long array {@code [domain, range]}
     * @throws IllegalArgumentException if the field type is not compatible with OPE
     */
    static long[] deriveOpeBounds(FieldType type) {
        assert type != null : "type must not be null";

        final long domain;

        if (type instanceof FieldType.Primitive p) {
            domain = switch (p) {
                case INT8 -> 256L;
                case INT16 -> 65_536L;
                case INT32 -> 1L << 32;
                case INT64, TIMESTAMP -> OPE_DOMAIN_CAP;
                default -> throw new IllegalArgumentException(
                        "OrderPreserving encryption is not supported for field type " + p);
            };
        } else if (type instanceof FieldType.BoundedString bs) {
            // Domain based on byte-space: 256^min(maxLength, 6)
            // The +1 accounts for the bytesToPositiveLong offset encoding
            final int effectiveLen = Math.min(bs.maxLength(), 6);
            long d = 1L;
            for (int i = 0; i < effectiveLen; i++) {
                d *= 256L;
                // Cap to prevent overflow
                if (d > OPE_DOMAIN_CAP) {
                    d = OPE_DOMAIN_CAP;
                    break;
                }
            }
            domain = d;
        } else {
            throw new IllegalArgumentException(
                    "OrderPreserving encryption is not supported for field type " + type);
        }

        assert domain >= 1 : "domain must be >= 1";
        final long range = Math.min(domain * OPE_RANGE_RATIO, Long.MAX_VALUE);
        assert range > domain : "range must be > domain";

        return new long[]{domain, range};
    }
}
